// Aceita tanto o Chat Trigger (teste manual) quanto o webhook da Evolution API (WhatsApp).
// Saída padronizada: mensagem, telefone, nome, sessionId

const input = $input.first().json;

let mensagem = '';
let telefone = '';
let nome = '';
let sessionId = '';
let canal = '';

if (input.chatInput !== undefined) {
  // --- Chat Trigger (teste dentro do n8n) ---
  canal = 'teste';
  mensagem = String(input.chatInput || '').trim();
  sessionId = input.sessionId || 'sessao-teste';
  telefone = 'teste-' + sessionId;
  nome = 'Cliente Teste';
} else {
  // --- Evolution API (WhatsApp) ---
  canal = 'whatsapp';
  const d = input.body?.data || input.data || input;
  const m = d.message || {};

  mensagem = String(
    m.conversation ||
    m.extendedTextMessage?.text ||
    m.imageMessage?.caption ||
    ''
  ).trim();

  const jid = d.key?.remoteJid || '';
  telefone = jid.split('@')[0];
  nome = d.pushName || telefone;
  sessionId = telefone;

  // Ignora mensagens enviadas pelo próprio número e grupos
  const daPropriaEmpresa = d.key?.fromMe === true;
  const ehGrupo = jid.includes('@g.us');
  if (daPropriaEmpresa || ehGrupo || !mensagem) {
    return [];
  }
}

if (!mensagem) {
  return [];
}

return [{ json: { mensagem, telefone, nome, sessionId, canal } }];

