// Lê o JSON que o classificador devolveu e junta com os dados da conversa.

const cfg = $('Config do Cliente').first().json;
const entrada = $('Normalizar Entrada').first().json;
const respostaBot = $('Agente FAQ').first().json.output || '';

let c = { temperatura: 'frio', interesse: 'Contato inicial', preco: null, precisa_humano: false };

try {
  const bruto = $input.first().json.choices?.[0]?.message?.content;
  if (bruto) {
    const parsed = JSON.parse(bruto);
    c = {
      temperatura: ['quente', 'morno', 'frio'].includes(parsed.temperatura) ? parsed.temperatura : 'frio',
      interesse: parsed.interesse || 'Contato inicial',
      preco: parsed.preco && parsed.preco !== 'null' ? parsed.preco : null,
      precisa_humano: parsed.precisa_humano === true,
    };
  }
} catch (e) {
  // Se a classificação falhar, seguimos com o padrão em vez de derrubar o atendimento.
  console.log('Falha ao classificar, usando padrão:', e.message);
}

return [{
  json: {
    slug: cfg.slug,
    nome_negocio: cfg.nome_negocio,
    supabase_url: cfg.supabase_url,
    evolution_url: cfg.evolution_url,
    evolution_instance: cfg.evolution_instance,
    telefone: entrada.telefone,
    nome: entrada.nome,
    canal: entrada.canal,
    mensagem_cliente: entrada.mensagem,
    resposta_bot: respostaBot,
    temperatura: c.temperatura,
    interesse: c.interesse,
    preco: c.preco,
    precisa_humano: c.precisa_humano,
  },
}];
